// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** The emergency department over a period (by the day of arrival). */
export interface ErStatisticsOut {
  date_from: string;
  date_to: string;
  triage_target_minutes: number;
  visits: number;
  still_open: number;
  triaged: number;
  seen_before_triage: number;
  median_minutes_to_triage: number | null;
  triaged_within_target_pct: number | null;
  medico_legal: number;
  medico_legal_undecided: number;
  medico_legal_cases_opened: number;
  by_level: ErLevelStatOut[];
  overrides: ErOverridesOut;
  dispositions: ErDispositionCountOut[];
  /** The waiting times MSDS 15 iii asks the SOP to set */
  waits: ErWaitStatOut[];
}

export interface ErLevelStatOut {
  level: number;
  name: string;
  colour: "Red" | "Orange" | "Yellow" | "Green" | "Blue" | "White" | "Black";
  target_minutes: number;
  visits: number;
  seen: number;
  median_minutes_to_doctor: number | null;
  seen_within_target_pct: number | null;
}

export interface ErOverridesOut {
  triages: number;
  made_more_urgent: number;
  made_less_urgent: number;
}

export interface ErDispositionCountOut {
  disposition: "Admitted" | "Discharged" | "Referred" | "LAMA" | "DischargedOnRequest" | "LeftWithoutBeingSeen" | "Died" | "BroughtDead";
  visits: number;
}

export interface ErWaitStatOut {
  wait: "Assessment" | "Observation" | "Admission" | "NoBed" | "Referral" | "LengthOfStay";
  label: string;
  patients: number;
  median_minutes: number | null;
  p90_minutes: number | null;
  max_minutes: number | null;
}

/** Emergency department statistics — GET /api/v1/er/statistics (who may call: holders of er.statistics.view). */
export function erStatistics(query?: { date_from?: string | null; date_to?: string | null }): Promise<ErStatisticsOut> {
  return api<ErStatisticsOut>("GET", withQuery(`/er/statistics`, query), undefined);
}
